import heapq

def match(orders):
    trades = []
    buy_heap = []  # (-price, time, id)
    sell_heap = []  # (price, time, id)
    book = {}  # id -> dict(side, price, qty, time, active)

    time_counter = 0

    for order in orders:
        time_counter += 1
        op = order[0]

        if op == 'cancel':
            oid = order[1]
            if oid in book:
                book[oid]['active'] = False
            continue

        if op == 'limit':
            _, oid, side, price, qty = order
        elif op == 'ioc':
            _, oid, side, price, qty = order
        elif op == 'market':
            _, oid, side, qty = order
            price = None
        else:
            continue

        remaining = qty

        if side == 'buy':
            # match against sell_heap
            while remaining > 0 and sell_heap:
                sp, stime, sid = sell_heap[0]
                if sid not in book or not book[sid]['active']:
                    heapq.heappop(sell_heap)
                    continue
                sell_order = book[sid]
                if sell_order['qty'] <= 0 or not sell_order['active']:
                    heapq.heappop(sell_heap)
                    continue

                if price is not None and sp > price:
                    break

                trade_qty = min(remaining, sell_order['qty'])
                trades.append([oid, sid, sp, trade_qty])

                remaining -= trade_qty
                sell_order['qty'] -= trade_qty

                if sell_order['qty'] == 0:
                    sell_order['active'] = False
                    heapq.heappop(sell_heap)

            if op == 'limit' and remaining > 0:
                book[oid] = {'side': 'buy', 'price': price, 'qty': remaining, 'time': time_counter, 'active': True}
                heapq.heappush(buy_heap, (-price, time_counter, oid))

        else:  # side == 'sell'
            # match against buy_heap
            while remaining > 0 and buy_heap:
                neg_bp, btime, bid = buy_heap[0]
                bp = -neg_bp
                if bid not in book or not book[bid]['active']:
                    heapq.heappop(buy_heap)
                    continue
                buy_order = book[bid]
                if buy_order['qty'] <= 0 or not buy_order['active']:
                    heapq.heappop(buy_heap)
                    continue

                if price is not None and bp < price:
                    break

                trade_qty = min(remaining, buy_order['qty'])
                trades.append([bid, oid, bp, trade_qty])

                remaining -= trade_qty
                buy_order['qty'] -= trade_qty

                if buy_order['qty'] == 0:
                    buy_order['active'] = False
                    heapq.heappop(buy_heap)

            if op == 'limit' and remaining > 0:
                book[oid] = {'side': 'sell', 'price': price, 'qty': remaining, 'time': time_counter, 'active': True}
                heapq.heappush(sell_heap, (price, time_counter, oid))

    return trades

